import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line_input = scanner.nextLine();
        StringBuilder output_str = new StringBuilder();
        int size = line_input.length();
        boolean at_present = false;

        // Check if '@' is present in the input
        for (int i = 0; i < size; i++) {
            if (line_input.charAt(i) == '@') {
                at_present = true;
                break;
            }
        }

        char[] chars = line_input.toCharArray();

        for (int i = 0; i < size; i++) {
            if (i + 2 < size && chars[i] == 'd' && chars[i + 1] == 'o' && chars[i + 2] == 't' && i != 0 && i != size - 3) {
                output_str.append('.');
                chars[i] = ' ';
                chars[i + 1] = ' ';
                chars[i + 2] = ' ';
            } else if (i + 1 < size && chars[i] == 'a' && chars[i + 1] == 't' && i != 0 && i != size - 2 && !at_present) {
                output_str.append('@');
                chars[i] = ' ';
                chars[i + 1] = ' ';
                at_present = true;
            } else if (chars[i] != ' ') {
                output_str.append(chars[i]);
            }
        }

        System.out.print(output_str.toString());
        scanner.close();
    }
}
